delivering_group.source:
@startuml
layout compact
[*] --> Delivering
state Delivering {
  [*] --> Driving
  Driving --> Waiting : arrived
  Waiting --> Unlocked : enterPin(code) [pin matches]
  Unlocked : exit / lockLid()
}
@enduml

delivering_border.source:
@startuml
layout compact
[*] --> Delivering
state Delivering {
  [*] --> Driving
  Driving --> Waiting : arrived
  Waiting --> Unlocked : enterPin(code) [pin matches]
  Unlocked : exit / lockLid()
}
Delivering --> Returning : when(battery < 15%)
@enduml
